import index from "./index.html"

const BACKEND = "http://127.0.0.1:3000"

Bun.serve({
  port: 5173,
  async fetch(req) {
    const url = new URL(req.url)
    if (!url.pathname.startsWith("/api/")) return
    return await fetch(new URL(url.pathname + url.search, BACKEND), {
      method: req.method,
      headers: req.headers,
      body: req.body,
    })
  },
  routes: { "/*": index },
})

