import { useEffect, useState, useCallback } from "react"
import { signOut } from "../lib/auth-client"
import type { Session } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface WalletAccount {
  id: string
  name: string
  userId: string
  accountNumber: string
  balance: number
  createdAt: string
  updatedAt: string | null
}

interface StandardResponse<T = unknown> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

export default function AccountPage({ user }: { user: Session["user"] }) {
  const [accounts, setAccounts] = useState<WalletAccount[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [creating, setCreating] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const [accountName, setAccountName] = useState("")

  const fetchAccounts = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: StandardResponse<WalletAccount[]> = await res.json()
      setAccounts(json.data ?? [])
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load accounts")
      setAccounts([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  const handleCreateAccount = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!accountName.trim()) return

    setCreating(true)
    setCreateError(null)

    const accountNumber = `WAVE-${Array.from({ length: 8 }, () =>
      "REDACTED"[Math.floor(Math.random() * 36)]
    ).join("")}`

    try {
      const res = await fetch("/api/wallet/accounts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: accountName.trim(),
          userId: user.id,
          accountNumber,
          balance: 0,
        }),
      })
      if (!res.ok) {
        const errJson: StandardResponse = await res.json()
        throw new Error(errJson.error ?? `HTTP ${res.status}`)
      }
      const json: StandardResponse<WalletAccount> = await res.json()
      if (json.data) {
        setAccounts((prev) => [...prev, json.data!])
      }
      setAccountName("")
    } catch (err) {
      setCreateError(err instanceof Error ? err.message : "Failed to create account")
    } finally {
      setCreating(false)
    }
  }

  const handleSignOut = async () => {
    await signOut()
  }

  const formatBalance = (balance: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(balance)

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-2xl font-bold tracking-tight text-foreground">Account</h1>
        <div className="flex items-center gap-2">
          <div className="flex flex-col items-end leading-tight px-3 border-r border-border">
            <span className="text-sm font-semibold text-foreground">{user.name}</span>
            <span className="text-xs text-muted-foreground">{user.email}</span>
          </div>
          <Button variant="outline" size="sm" onClick={fetchAccounts} disabled={loading}>
            Refresh
          </Button>
          <Button variant="destructive" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6 space-y-8">
        <Card>
          <CardHeader>
            <CardTitle>Profile</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex justify-between items-center py-2 border-b border-border/50">
              <span className="text-sm text-muted-foreground">Name</span>
              <span className="text-sm font-medium text-foreground">{user.name}</span>
            </div>
            <div className="flex justify-between items-center py-2 border-b border-border/50">
              <span className="text-sm text-muted-foreground">Email</span>
              <span className="text-sm font-medium text-foreground">{user.email}</span>
            </div>
            <div className="flex justify-between items-center py-2 border-b border-border/50">
              <span className="text-sm text-muted-foreground">User ID</span>
              <span className="text-sm font-mono text-muted-foreground">{user.id}</span>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle>Wallet Accounts</CardTitle>
            <span className="text-sm text-muted-foreground">{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
          </CardHeader>
          <CardContent className="space-y-4">
            {loading && (
              <div className="space-y-3">
                {Array.from({ length: 2 }).map((_, i) => (
                  <Skeleton key={i} className="h-16 w-full rounded-lg" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-6 text-center">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchAccounts}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && accounts.length === 0 && (
              <div className="py-6 text-center">
                <p className="text-sm text-muted-foreground">No accounts yet. Create one below.</p>
              </div>
            )}

            {!loading && !error && accounts.length > 0 && (
              <div className="space-y-2">
                {accounts.map((acc) => (
                  <div
                    key={acc.id}
                    className="flex items-center justify-between p-4 rounded-lg border border-border bg-card transition-colors hover:bg-accent-subtle/50"
                  >
                    <div className="flex flex-col gap-1">
                      <span className="text-sm font-semibold text-foreground">{acc.name}</span>
                      <span className="text-xs font-mono text-muted-foreground">{acc.accountNumber}</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-sm font-semibold font-mono text-foreground">
                        {formatBalance(acc.balance)}
                      </span>
                      <Badge variant="secondary" className="text-xs">
                        Active
                      </Badge>
                    </div>
                  </div>
                ))}
              </div>
            )}

            <form onSubmit={handleCreateAccount} className="space-y-3 pt-4 border-t border-border">
              <div className="space-y-1.5">
                <Label htmlFor="account-name">New Account Name</Label>
                <Input
                  id="account-name"
                  placeholder="e.g. Checking, Savings"
                  value={accountName}
                  onChange={(e) => setAccountName(e.target.value)}
                  disabled={creating}
                />
              </div>
              {createError && (
                <p className="text-sm text-destructive">{createError}</p>
              )}
              <Button type="submit" disabled={creating || !accountName.trim()} className="w-full">
                {creating ? "Creating..." : "Create Account"}
              </Button>
            </form>
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
      </footer>
    </>
  )
}

