import { useEffect, useState, useCallback } from "react"
import { signOut } from "../lib/auth-client"
import type { Session } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface WalletAccount {
  id: string
  name: string
  userId: string
  accountNumber: string
  balance: number
  createdAt: string
  updatedAt: string | null
}

interface WalletTransaction {
  id: string
  userId: string
  senderAccountId: string
  senderName: string
  receiverAccountId: string
  receiverName: string
  amount: string
  status: "pending" | "success" | "failed"
  createdAt: string
  updatedAt?: string | null
}

interface StandardResponse<T = unknown> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

export default function HomePage({
  user,
  onNavigate,
}: {
  user: Session["user"]
  onNavigate: (page: "notifications" | "account") => void
}) {
  const [accounts, setAccounts] = useState<WalletAccount[]>([])
  const [transactions, setTransactions] = useState<WalletTransaction[]>([])
  const [loadingAccounts, setLoadingAccounts] = useState(true)
  const [loadingTransactions, setLoadingTransactions] = useState(true)

  const fetchAccounts = useCallback(async () => {
    setLoadingAccounts(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (res.ok) {
        const json: StandardResponse<WalletAccount[]> = await res.json()
        setAccounts(json.data ?? [])
      }
    } catch {
      setAccounts([])
    } finally {
      setLoadingAccounts(false)
    }
  }, [user.id])

  const fetchTransactions = useCallback(async () => {
    setLoadingTransactions(true)
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/transactions`)
      if (res.ok) {
        const json: StandardResponse<WalletTransaction[]> = await res.json()
        const sorted = (json.data ?? []).sort(
          (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
        )
        setTransactions(sorted.slice(0, 5))
      }
    } catch {
      setTransactions([])
    } finally {
      setLoadingTransactions(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
    fetchTransactions()
  }, [fetchAccounts, fetchTransactions])

  const totalBalance = accounts.reduce((sum, a) => sum + a.balance, 0)

  const formatBalance = (balance: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(balance)

  const formatDate = (iso: string) =>
    new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <div className="flex items-center gap-3">
          <h1 className="text-xl font-bold tracking-tight text-foreground">Wave</h1>
        </div>
        <div className="flex items-center gap-2">
          <div className="flex flex-col items-end leading-tight px-3 border-r border-border">
            <span className="text-sm font-semibold text-foreground">{user.name}</span>
            <span className="text-xs text-muted-foreground">{user.email}</span>
          </div>
          <Button variant="outline" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-8">
        <section className="space-y-1">
          <p className="text-sm text-muted-foreground">Welcome back</p>
          <h2 className="text-3xl font-bold tracking-tight text-foreground">{user.name}</h2>
        </section>

        <Card>
          <CardHeader className="pb-3">
            <CardTitle className="text-base font-medium text-muted-foreground">
              Total Balance
            </CardTitle>
          </CardHeader>
          <CardContent>
            {loadingAccounts ? (
              <Skeleton className="h-10 w-48 rounded-md" />
            ) : (
              <p className="text-3xl font-bold font-mono text-foreground">
                {formatBalance(totalBalance)}
              </p>
            )}
            <p className="text-xs text-muted-foreground mt-1">
              Across {accounts.length} account{accounts.length !== 1 ? "s" : ""}
            </p>
          </CardContent>
        </Card>

        <div className="grid grid-cols-2 gap-4">
          <Button
            variant="default"
            size="lg"
            className="h-20 text-base font-semibold flex flex-col items-center justify-center gap-1"
            onClick={() => onNavigate("account")}
          >
            <span className="text-lg">+</span>
            <span>Add Money</span>
          </Button>
          <Button
            variant="outline"
            size="lg"
            className="h-20 text-base font-semibold flex flex-col items-center justify-center gap-1"
            onClick={() => onNavigate("account")}
          >
            <span className="text-lg">&uarr;</span>
            <span>Send Money</span>
          </Button>
        </div>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-3">
            <CardTitle className="text-base font-medium">Recent Activity</CardTitle>
            <Button variant="ghost" size="xs" onClick={() => onNavigate("account")}>
              View all
            </Button>
          </CardHeader>
          <CardContent>
            {loadingTransactions && (
              <div className="space-y-3">
                {Array.from({ length: 3 }).map((_, i) => (
                  <Skeleton key={i} className="h-12 w-full rounded-md" />
                ))}
              </div>
            )}

            {!loadingTransactions && transactions.length === 0 && (
              <div className="py-6 text-center">
                <p className="text-sm text-muted-foreground">No transactions yet.</p>
                <Button variant="link" size="sm" className="mt-1" onClick={() => onNavigate("account")}>
                  Add money to get started
                </Button>
              </div>
            )}

            {!loadingTransactions && transactions.length > 0 && (
              <div className="space-y-1">
                {transactions.map((tx) => (
                  <div
                    key={tx.id}
                    className="flex items-center justify-between py-2.5 border-b border-border/50 last:border-0"
                  >
                    <div className="flex flex-col">
                      <span className="text-sm font-medium text-foreground">
                        {tx.senderName === tx.receiverName
                          ? "Deposit"
                          : `To ${tx.receiverName}`}
                      </span>
                      <span className="text-xs text-muted-foreground">
                        {formatDate(tx.createdAt)}
                      </span>
                    </div>
                    <div className="flex items-center gap-2">
                      <span className="text-sm font-mono font-semibold text-foreground">
