          </div>
        </div>
      </div>
    )
  }

  const activeSession = session ?? (backendOff ? {
    user: { id: "dev_user", name: "Alex Rivera", email: "alex@wave.dev", emailVerified: true, createdAt: new Date(), updatedAt: new Date() },
    session: { id: "dev_session", expiresAt: new Date(Date.now() + 86400000) },
  } as Session : null)

  if (!activeSession) {
    return (
      <div className="flex min-h-screen flex-col bg-background text-foreground animate-fade-slide-in">
        <AuthPage />
      </div>
    )
  }

  return (
    <div className="flex min-h-screen flex-col bg-background text-foreground animate-fade-slide-in">
      <nav className="flex items-center gap-1 px-8 py-3 border-b border-border bg-card">
        <Button
          variant={page === "home" ? "default" : "ghost"}
          size="sm"
          onClick={() => navigate("home")}
        >
          Home
        </Button>
        <Button
          variant={page === "notifications" ? "default" : "ghost"}
          size="sm"
          onClick={() => navigate("notifications")}
        >
          Notifications
        </Button>
        <Button
          variant={page === "account" ? "default" : "ghost"}
          size="sm"
          onClick={() => navigate("account")}
