import { useEffect, useState, useCallback } from "react"
import { signOut } from "../lib/auth-client"
import type { Session } from "../lib/auth-client"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface Transaction {
  id: string
  userId: string
  senderAccountId: string
  senderName: string
  receiverAccountId: string
  receiverName: string
  amount: string
  status: "pending" | "success" | "failed"
  createdAt: string
  updatedAt?: string | null
}

interface WalletAccount {
  id: string
  name: string
  userId: string
  accountNumber: string
  balance: number
  createdAt: string
  updatedAt: string | null
}

interface StandardResponse<T = unknown> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

type Filter = "all" | "success" | "failed" | "pending"

export default function TransactionsPage({ user }: { user: Session["user"] }) {
  const [transactions, setTransactions] = useState<Transaction[]>([])
  const [accounts, setAccounts] = useState<WalletAccount[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [filter, setFilter] = useState<Filter>("all")

  const fetchTransactions = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      const accountIds = accounts.length > 0
        ? accounts.map((a) => a.id)
        : await fetch(`/api/wallet/users/${user.id}/accounts`).then((r) =>
            r.json()
          ).then((j: StandardResponse<WalletAccount[]>) => {
            const data = j.data ?? []
            setAccounts(data)
            return data.map((a) => a.id)
          })

      const res = await fetch(`/api/wallet/users/${user.id}/transactions`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: StandardResponse<Transaction[]> = await res.json()
      const sorted = (json.data ?? []).sort(
        (a, b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime()
      )
      setTransactions(sorted)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load transactions")
      setTransactions([])
    } finally {
      setLoading(false)
    }
  }, [user.id, accounts.length])

  const fetchAccounts = useCallback(async () => {
    try {
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (res.ok) {
        const json: StandardResponse<WalletAccount[]> = await res.json()
        setAccounts(json.data ?? [])
      }
    } catch {
      setAccounts([])
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (accounts.length > 0 || !loading) {
      fetchTransactions()
    }
  }, [user.id, accounts.length])

  const filtered = filter === "all"
    ? transactions
    : transactions.filter((tx) => tx.status === filter)

  const handleSignOut = async () => {
    await signOut()
  }

  const formatBalance = (balance: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(balance)

  const formatDate = (iso: string) =>
    new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" }).format(new Date(iso))

  const userAccountIds = new Set(accounts.map((a) => a.id))

  const getDirection = (tx: Transaction): "in" | "out" | "self" => {
    if (tx.senderName === tx.receiverName) return "self"
    if (userAccountIds.has(tx.receiverAccountId) && !userAccountIds.has(tx.senderAccountId)) return "in"
    return "out"
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-xl font-bold tracking-tight text-foreground">Transactions</h1>
        <div className="flex items-center gap-2">
          <div className="flex flex-col items-end leading-tight px-3 border-r border-border">
            <span className="text-sm font-semibold text-foreground">{user.name}</span>
            <span className="text-xs text-muted-foreground">{user.email}</span>
          </div>
          <Button variant="outline" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-8 space-y-6">
        <div className="flex items-center gap-2">
          {(["all", "success", "pending", "failed"] as const).map((f) => (
            <Button
              key={f}
              variant={filter === f ? "default" : "outline"}
              size="sm"
              onClick={() => setFilter(f)}
              className="capitalize"
            >
              {f}
            </Button>
          ))}
        </div>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between pb-3">
            <CardTitle className="text-base font-medium">
              {filter === "all" ? "All Transactions" : `${filter.charAt(0).toUpperCase() + filter.slice(1)} Transactions`}
            </CardTitle>
            <span className="text-xs text-muted-foreground">{filtered.length} total</span>
          </CardHeader>
          <CardContent>
            {loading && (
              <div className="space-y-3">
                {Array.from({ length: 5 }).map((_, i) => (
                  <Skeleton key={i} className="h-14 w-full rounded-md" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-8 text-center">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchTransactions}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && filtered.length === 0 && (
              <div className="py-8 text-center">
                <p className="text-sm text-muted-foreground">
                  {transactions.length === 0
                    ? "No transactions yet. Deposit funds to get started."
                    : `No ${filter !== "all" ? filter : ""} transactions found.`}
                </p>
              </div>
            )}

            {!loading && !error && filtered.length > 0 && (
              <div className="divide-y divide-border/50">
                {filtered.map((tx) => {
                  const dir = getDirection(tx)
                  return (
                    <div
                      key={tx.id}
                      className="flex items-center justify-between py-3.5 first:pt-0 last:pb-0"
                    >
                      <div className="flex items-center gap-3 min-w-0">
                        <div className="shrink-0 w-9 h-9 rounded-full flex items-center justify-center text-sm font-semibold bg-secondary text-secondary-foreground">
                          {dir === "in" ? "\u2190" : dir === "self" ? "\u21C4" : "\u2192"}
                        </div>
                        <div className="min-w-0">
                          <p className="text-sm font-medium text-foreground truncate">
                            {dir === "self"
                              ? "Deposit"
                              : dir === "in"
                                ? `From ${tx.senderName}`
                                : `To ${tx.receiverName}`}
                          </p>
                          <p className="text-xs text-muted-foreground">{formatDate(tx.createdAt)}</p>
                        </div>
                      </div>
                      <div className="flex items-center gap-3 shrink-0">
                        <span className={`text-sm font-mono font-semibold ${
                          dir === "in" ? "text-success" : "text-foreground"
                        }`}>
                          {dir === "in" ? "+" : dir === "out" ? "\u2212" : ""}{formatBalance(Number(tx.amount))}
                        </span>
                        <Badge
                          variant={tx.status === "success" ? "default" : tx.status === "failed" ? "destructive" : "secondary"}
                          className="text-[10px] px-1.5 py-0"
                        >
                          {tx.status}
                        </Badge>
                      </div>
                    </div>
                  )
                })}
              </div>
            )}
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{filtered.length} transaction{filtered.length !== 1 ? "s" : ""}</span>
      </footer>
    </>
  )
}

