import { createRouter, createRootRoute, createRoute, Outlet, Link } from "@tanstack/react-router"
import { useState, useEffect } from "react"
import { useSession } from "./lib/auth-client"
import type { Session } from "./lib/auth-client"
import { UserProvider } from "./lib/user-context"
import { Skeleton } from "./components/ui/skeleton"
import { Button } from "./components/ui/button"
import AuthPage from "./components/AuthPage"
import HomePage from "./pages/HomePage"
import NotificationPage from "./components/NotificationPage"
import TransactionsPage from "./pages/TransactionsPage"
import AccountPage from "./pages/AccountPage"

const linkBase =
  "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 h-9 px-4 py-2"

const navItems = [
  { to: "/", label: "Home" },
  { to: "/notifications", label: "Notifications" },
  { to: "/transactions", label: "Transactions" },
  { to: "/account", label: "Account" },
] as const

function RootLayout() {
  const { data: session, isPending } = useSession()
  const [backendOff, setBackendOff] = useState(false)

  useEffect(() => {
    if (!isPending) return
    const timer = setTimeout(() => {
      if (typeof window !== "undefined") {
        fetch("/api/auth/session", { method: "HEAD", signal: AbortSignal.timeout(1000) }).catch(() =>
          setBackendOff(true)
        )
      }
    }, 2000)
    return () => clearTimeout(timer)
  }, [isPending])

  if (isPending && !backendOff) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-8">
        <div className="w-full max-w-sm space-y-4">
          <div className="space-y-2 text-center">
            <Skeleton className="h-8 w-3/4 mx-auto rounded-md" />
            <Skeleton className="h-4 w-1/2 mx-auto rounded-md" />
          </div>
          <div className="space-y-3 pt-4">
            <Skeleton className="h-4 w-full rounded-md" />
            <Skeleton className="h-4 w-full rounded-md" />
            <Skeleton className="h-10 w-full rounded-md" />
          </div>
        </div>
      </div>
    )
  }

  const activeSession = session ?? (backendOff
    ? ({
        user: {
          id: "dev_user",
          name: "Alex Rivera",
          email: "alex@wave.dev",
          emailVerified: true,
          createdAt: new Date(),
          updatedAt: new Date(),
        },
        session: { id: "dev_session", expiresAt: new Date(Date.now() + 86400000) },
      } as Session)
    : null)

  if (!activeSession) {
    return (
      <div className="flex min-h-screen flex-col bg-background text-foreground animate-fade-slide-in">
        <AuthPage />
      </div>
    )
  }

  return (
    <UserProvider user={activeSession.user}>
      <div className="flex min-h-screen flex-col bg-background text-foreground animate-fade-slide-in">
        <nav className="flex items-center gap-1 px-8 py-3 border-b border-border bg-card">
          {navItems.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              className={linkBase}
              activeProps={{ className: "bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground" }}
              inactiveProps={{ className: "hover:bg-accent hover:text-accent-foreground" }}
            >
              {item.label}
            </Link>
          ))}
        </nav>
        <Outlet />
      </div>
    </UserProvider>
  )
}

const rootRoute = createRootRoute({
  component: RootLayout,
})

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/",
  component: HomePage,
})

const notificationsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/notifications",
  component: NotificationPage,
})

const transactionsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/transactions",
  component: TransactionsPage,
})

const accountRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account",
  component: AccountPage,
})

const routeTree = rootRoute.addChildren([indexRoute, notificationsRoute, transactionsRoute, accountRoute])

const router = createRouter({ routeTree })

declare module "@tanstack/react-router" {
  interface Register {
    router: typeof router
  }
}

export { router, rootRoute }

import { useState, useEffect } from "react"
import { Outlet, Link } from "@tanstack/react-router"
import { useSession } from "./lib/auth-client"
import type { Session } from "./lib/auth-client"
import { UserProvider } from "./lib/user-context"
import { Skeleton } from "./components/ui/skeleton"
import AuthPage from "./components/AuthPage"

const linkBase =
  "inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50 h-9 px-4 py-2"

const navItems = [
  { to: "/", label: "Home" },
  { to: "/notifications", label: "Notifications" },
  { to: "/transactions", label: "Transactions" },
  { to: "/account", label: "Account" },
] as const

export default function App() {
  const { data: session, isPending } = useSession()
  const [backendOff, setBackendOff] = useState(false)

  useEffect(() => {
    if (!isPending) return
    const timer = setTimeout(() => {
      if (typeof window !== "undefined") {
        fetch("/api/auth/session", { method: "HEAD", signal: AbortSignal.timeout(1000) }).catch(() =>
          setBackendOff(true)
        )
      }
    }, 2000)
    return () => clearTimeout(timer)
  }, [isPending])

  if (isPending && !backendOff) {
    return (
      <div className="flex min-h-screen items-center justify-center bg-background p-8">
        <div data-testid="loading-skeleton" className="w-full max-w-sm space-y-4">
          <div className="space-y-2 text-center">
            <Skeleton className="h-8 w-3/4 mx-auto rounded-md" />
            <Skeleton className="h-4 w-1/2 mx-auto rounded-md" />
          </div>
          <div className="space-y-3 pt-4">
            <Skeleton className="h-4 w-full rounded-md" />
            <Skeleton className="h-4 w-full rounded-md" />
            <Skeleton className="h-10 w-full rounded-md" />
          </div>
        </div>
      </div>
    )
  }

  const activeSession = session ?? (backendOff
    ? ({
        user: {
          id: "dev_user",
          name: "Alex Rivera",
          email: "alex@wave.dev",
          emailVerified: true,
          createdAt: new Date(),
          updatedAt: new Date(),
        },
        session: { id: "dev_session", expiresAt: new Date(Date.now() + 86400000) },
      } as Session)
    : null)

  if (!activeSession) {
    return (
      <div className="flex min-h-screen flex-col bg-background text-foreground animate-fade-slide-in">
        <AuthPage />
      </div>
    )
  }

  return (
    <UserProvider user={activeSession.user}>
      <div className="flex min-h-screen flex-col bg-background text-foreground animate-fade-slide-in">
        <nav className="flex items-center gap-1 px-8 py-3 border-b border-border bg-card">
          {navItems.map((item) => (
            <Link
              key={item.to}
              to={item.to}
              className={linkBase}
              activeProps={{ className: "bg-primary text-primary-foreground hover:bg-primary hover:text-primary-foreground" }}
              inactiveProps={{ className: "hover:bg-accent hover:text-accent-foreground" }}
            >
              {item.label}
            </Link>
          ))}
        </nav>
        <Outlet />
      </div>
    </UserProvider>
  )
}

import { createRouter, createRootRoute, createRoute } from "@tanstack/react-router"
import App from "./App"
import HomePage from "./pages/HomePage"
import NotificationPage from "./components/NotificationPage"
import TransactionsPage from "./pages/TransactionsPage"
import AccountPage from "./pages/AccountPage"

const rootRoute = createRootRoute({
  component: App,
})

const indexRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/",
  component: HomePage,
})

const notificationsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/notifications",
  component: NotificationPage,
})

const transactionsRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/transactions",
  component: TransactionsPage,
})

const accountRoute = createRoute({
  getParentRoute: () => rootRoute,
  path: "/account",
  component: AccountPage,
})

