import { useEffect, useState, useCallback } from "react"
import { useSearch } from "@tanstack/react-router"
import { signOut } from "../lib/auth-client"
import { useUser } from "../lib/user-context"
import { Card, CardContent, CardHeader, CardTitle } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Input } from "../components/ui/input"
import { Label } from "../components/ui/label"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface WalletAccount {
  id: string
  name: string
  userId: string
  accountNumber: string
  balance: number
  createdAt: string
  updatedAt: string | null
}

interface WalletTransaction {
  id: string
  userId: string
  senderAccountId: string
  senderName: string
  receiverAccountId: string
  receiverName: string
  amount: string
  status: "pending" | "success" | "failed"
  createdAt: string
  updatedAt?: string | null
}

interface StandardResponse<T = unknown> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

export default function AccountPage() {
  const user = useUser()
  const search = useSearch({ strict: false }) as { section?: string }
  const initialSection = search.section ?? null

  const [accounts, setAccounts] = useState<WalletAccount[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [creating, setCreating] = useState(false)
  const [createError, setCreateError] = useState<string | null>(null)
  const [accountName, setAccountName] = useState("")

  const [depositAccountId, setDepositAccountId] = useState("")
  const [depositAmount, setDepositAmount] = useState("")
  const [depositing, setDepositing] = useState(false)
  const [depositError, setDepositError] = useState<string | null>(null)
  const [depositSuccess, setDepositSuccess] = useState<WalletAccount | null>(null)

  const [transferring, setTransferring] = useState(false)
  const [transferError, setTransferError] = useState<string | null>(null)
  const [transferSuccess, setTransferSuccess] = useState<WalletTransaction | null>(null)
  const [senderId, setSenderId] = useState("")
  const [receiverNumber, setReceiverNumber] = useState("")
  const [amount, setAmount] = useState("")
  const [receiverLookup, setReceiverLookup] = useState<{ name: string; id: string } | null>(null)
  const [lookingUp, setLookingUp] = useState(false)

  const fetchAccounts = useCallback(async () => {
    try {
      setLoading(true)
      setError(null)
      const res = await fetch(`/api/wallet/users/${user.id}/accounts`)
      if (!res.ok) throw new Error(`HTTP ${res.status}`)
      const json: StandardResponse<WalletAccount[]> = await res.json()
      const data = json.data ?? []
      setAccounts(data)
      if (data.length > 0 && !senderId) {
        setSenderId(data[0]!.id)
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load accounts")
      setAccounts([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  useEffect(() => {
    fetchAccounts()
  }, [fetchAccounts])

  useEffect(() => {
    if (initialSection === "deposit") {
      const el = document.getElementById("deposit-section")
      if (el) el.scrollIntoView({ behavior: "smooth" })
      setDepositAccountId(accounts.length > 0 ? accounts[0]!.id : "")
    }
  }, [initialSection, accounts])

  useEffect(() => {
    if (!receiverNumber.trim() || receiverNumber.length < 8) {
      setReceiverLookup(null)
      return
    }
    const timer = setTimeout(async () => {
      setLookingUp(true)
      try {
        const res = await fetch(`/api/wallet/accounts/by-number/${encodeURIComponent(receiverNumber.trim())}`)
        if (res.ok) {
          const json: StandardResponse<WalletAccount> = await res.json()
          if (json.data) {
            setReceiverLookup({ name: json.data.name, id: json.data.id })
          } else {
            setReceiverLookup(null)
          }
        } else {
          setReceiverLookup(null)
        }
      } catch {
        setReceiverLookup(null)
      } finally {
        setLookingUp(false)
      }
    }, 400)
    return () => clearTimeout(timer)
  }, [receiverNumber])

  const handleCreateAccount = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!accountName.trim()) return

    setCreating(true)
    setCreateError(null)

    const accountNumber = `WAVE-${Array.from({ length: 8 }, () =>
      "REDACTED"[Math.floor(Math.random() * 36)]
    ).join("")}`

    try {
      const res = await fetch("/api/wallet/accounts", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: accountName.trim(),
          userId: user.id,
          accountNumber,
          balance: 0,
        }),
      })
      if (!res.ok) {
        const errJson: StandardResponse = await res.json()
        throw new Error(errJson.error ?? `HTTP ${res.status}`)
      }
      const json: StandardResponse<WalletAccount> = await res.json()
      if (json.data) {
        setAccounts((prev) => [...prev, json.data!])
      }
      setAccountName("")
    } catch (err) {
      setCreateError(err instanceof Error ? err.message : "Failed to create account")
    } finally {
      setCreating(false)
    }
  }

  const handleDeposit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!depositAccountId || !depositAmount.trim()) return

    setDepositing(true)
    setDepositError(null)
    setDepositSuccess(null)

    try {
      const res = await fetch("/api/wallet/accounts/" + depositAccountId + "/deposit", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId: user.id,
          accountId: depositAccountId,
          amount: Number.parseFloat(depositAmount),
        }),
      })
      if (!res.ok) {
        const errJson: StandardResponse = await res.json()
        throw new Error(errJson.error ?? `HTTP ${res.status}`)
      }
      const json: StandardResponse<WalletAccount> = await res.json()
      if (json.data) {
        setDepositSuccess(json.data)
      }
      setDepositAmount("")
      fetchAccounts()
    } catch (err) {
      setDepositError(err instanceof Error ? err.message : "Failed to deposit funds")
    } finally {
      setDepositing(false)
    }
  }

  const handleTransfer = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!senderId || !receiverLookup || !amount.trim()) return

    setTransferring(true)
    setTransferError(null)
    setTransferSuccess(null)

    const sender = accounts.find((a) => a.id === senderId)

    try {
      const res = await fetch("/api/wallet/transfers", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          userId: user.id,
          senderAccountId: senderId,
          senderName: sender?.name ?? "Unknown",
          receiverAccountId: receiverLookup.id,
          receiverName: receiverLookup.name,
          amount: Number.parseFloat(amount),
        }),
      })
      if (!res.ok) {
        const errJson: StandardResponse = await res.json()
        throw new Error(errJson.error ?? `HTTP ${res.status}`)
      }
      const json: StandardResponse<WalletTransaction> = await res.json()
      if (json.data) {
        setTransferSuccess(json.data)
      }
      setSenderId("")
      setReceiverNumber("")
      setAmount("")
      setReceiverLookup(null)
      fetchAccounts()
    } catch (err) {
      setTransferError(err instanceof Error ? err.message : "Failed to send transfer")
    } finally {
      setTransferring(false)
    }
  }

  const handleSignOut = async () => {
    await signOut()
  }

  const formatBalance = (balance: number) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(balance)

  const formatAmount = (amount: string) =>
    new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" }).format(Number(amount))

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-2xl font-bold tracking-tight text-foreground">Account</h1>
        <div className="flex items-center gap-2">
          <div className="flex flex-col items-end leading-tight px-3 border-r border-border">
            <span className="text-sm font-semibold text-foreground">{user.name}</span>
            <span className="text-xs text-muted-foreground">{user.email}</span>
          </div>
          <Button variant="outline" size="sm" onClick={fetchAccounts} disabled={loading}>
            Refresh
          </Button>
          <Button variant="destructive" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6 space-y-8">
        <Card>
          <CardHeader>
            <CardTitle>Profile</CardTitle>
          </CardHeader>
          <CardContent className="space-y-3">
            <div className="flex justify-between items-center py-2 border-b border-border/50">
              <span className="text-sm text-muted-foreground">Name</span>
              <span className="text-sm font-medium text-foreground">{user.name}</span>
            </div>
            <div className="flex justify-between items-center py-2 border-b border-border/50">
              <span className="text-sm text-muted-foreground">Email</span>
              <span className="text-sm font-medium text-foreground">{user.email}</span>
            </div>
            <div className="flex justify-between items-center py-2 border-b border-border/50">
              <span className="text-sm text-muted-foreground">User ID</span>
              <span className="text-sm font-mono text-muted-foreground">{user.id}</span>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader className="flex flex-row items-center justify-between">
            <CardTitle>Wallet Accounts</CardTitle>
            <span className="text-sm text-muted-foreground">{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
          </CardHeader>
          <CardContent className="space-y-4">
            {loading && (
              <div className="space-y-3">
                {Array.from({ length: 2 }).map((_, i) => (
                  <Skeleton key={i} className="h-16 w-full rounded-lg" />
                ))}
              </div>
            )}

            {error && !loading && (
              <div className="flex flex-col items-center gap-3 py-6 text-center">
                <p className="text-sm text-muted-foreground">{error}</p>
                <Button variant="outline" size="sm" onClick={fetchAccounts}>
                  Retry
                </Button>
              </div>
            )}

            {!loading && !error && accounts.length === 0 && (
              <div className="py-6 text-center">
                <p className="text-sm text-muted-foreground">No accounts yet. Create one below.</p>
              </div>
            )}

            {!loading && !error && accounts.length > 0 && (
              <div className="space-y-2">
                {accounts.map((acc) => (
                  <div
                    key={acc.id}
                    className="flex items-center justify-between p-4 rounded-lg border border-border bg-card transition-colors hover:bg-accent-subtle/50"
                  >
                    <div className="flex flex-col gap-1">
                      <span className="text-sm font-semibold text-foreground">{acc.name}</span>
                      <span className="text-xs font-mono text-muted-foreground">{acc.accountNumber}</span>
                    </div>
                    <div className="flex items-center gap-3">
                      <span className="text-sm font-semibold font-mono text-foreground">
                        {formatBalance(acc.balance)}
                      </span>
                      <Badge variant="secondary" className="text-xs">
                        Active
                      </Badge>
                    </div>
                  </div>
                ))}
              </div>
            )}

            <form onSubmit={handleCreateAccount} className="space-y-3 pt-4 border-t border-border">
              <div className="space-y-1.5">
                <Label htmlFor="account-name">New Account Name</Label>
                <Input
                  id="account-name"
                  placeholder="e.g. Checking, Savings"
                  value={accountName}
                  onChange={(e) => setAccountName(e.target.value)}
                  disabled={creating}
                />
              </div>
              {createError && (
                <p className="text-sm text-destructive">{createError}</p>
              )}
              <Button type="submit" disabled={creating || !accountName.trim()} className="w-full">
                {creating ? "Creating..." : "Create Account"}
              </Button>
            </form>
          </CardContent>
        </Card>

        <Card id="deposit-section">
          <CardHeader>
            <CardTitle>Add Money</CardTitle>
          </CardHeader>
          <CardContent>
            {depositSuccess ? (
              <div className="space-y-4 animate-fade-slide-in">
                <div className="rounded-lg border border-success/30 bg-success/5 p-4 text-center">
                  <p className="text-sm font-semibold text-success">Deposit completed</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    {formatBalance(Number(depositSuccess.balance))} in {depositSuccess.name}
                  </p>
                </div>
                <Button variant="outline" size="sm" className="w-full" onClick={() => setDepositSuccess(null)}>
                  Deposit again
                </Button>
              </div>
            ) : (
              <form onSubmit={handleDeposit} className="space-y-4">
                <div className="space-y-1.5">
                  <Label htmlFor="deposit-account">Into</Label>
                  <select
                    id="deposit-account"
                    value={depositAccountId}
                    onChange={(e) => setDepositAccountId(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                    required
                  >
                    <option value="" disabled>Select an account</option>
                    {accounts.map((acc) => (
                      <option key={acc.id} value={acc.id}>
                        {acc.name} ({acc.accountNumber}) — {formatBalance(acc.balance)}
                      </option>
                    ))}
                  </select>
                </div>
                <div className="space-y-1.5">
                  <Label htmlFor="deposit-amount">Amount (USD)</Label>
                  <Input
                    id="deposit-amount"
                    type="number"
                    step="0.01"
                    min="0.01"
                    placeholder="0.00"
                    value={depositAmount}
                    onChange={(e) => setDepositAmount(e.target.value)}
                  />
                </div>
                {depositError && (
                  <p className="text-sm text-destructive">{depositError}</p>
                )}
                <Button
                  type="submit"
                  disabled={!depositAccountId || !depositAmount.trim() || Number(depositAmount) <= 0}
                  className="w-full"
                >
                  Add Money
                </Button>
              </form>
            )}
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Send Money</CardTitle>
          </CardHeader>
          <CardContent>
            {transferSuccess ? (
              <div className="space-y-4 animate-fade-slide-in">
                <div className="rounded-lg border border-success/30 bg-success/5 p-4 text-center">
                  <p className="text-sm font-semibold text-success">Transfer completed</p>
                  <p className="text-xs text-muted-foreground mt-1">
                    {formatAmount(transferSuccess.amount)} from {transferSuccess.senderName} to {transferSuccess.receiverName}
                  </p>
                </div>
                <Button variant="outline" size="sm" className="w-full" onClick={() => setTransferSuccess(null)}>
                  Send another
                </Button>
              </div>
            ) : (
              <form onSubmit={handleTransfer} className="space-y-4">
                <div className="space-y-1.5">
                  <Label htmlFor="sender">From</Label>
                  <select
                    id="sender"
                    value={senderId}
                    onChange={(e) => setSenderId(e.target.value)}
                    className="flex h-10 w-full rounded-md border border-input bg-background px-3 py-2 text-sm ring-offset-background focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2"
                    required
                  >
                    <option value="" disabled>Select an account</option>
                    {accounts.map((acc) => (
                      <option key={acc.id} value={acc.id}>
                        {acc.name} ({acc.accountNumber}) — {formatBalance(acc.balance)}
                      </option>
                    ))}
                  </select>
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="receiver">To (account number)</Label>
                  <Input
                    id="receiver"
                    placeholder="e.g. WAVE-XXXXXXXX"
                    value={receiverNumber}
                    onChange={(e) => setReceiverNumber(e.target.value)}
                  />
                  {lookingUp && (
                    <p className="text-xs text-muted-foreground">Looking up account...</p>
                  )}
                  {receiverLookup && !lookingUp && (
                    <p className="text-xs font-medium text-success">{receiverLookup.name}</p>
                  )}
                  {!receiverLookup && !lookingUp && receiverNumber.length >= 8 && (
                    <p className="text-xs text-muted-foreground">No account found with that number</p>
                  )}
                </div>

                <div className="space-y-1.5">
                  <Label htmlFor="amount">Amount (USD)</Label>
                  <Input
                    id="amount"
                    type="number"
                    step="0.01"
                    min="0.01"
                    placeholder="0.00"
                    value={amount}
                    onChange={(e) => setAmount(e.target.value)}
                  />
                </div>

                {transferError && (
                  <p className="text-sm text-destructive">{transferError}</p>
                )}

                <Button
                  type="submit"
                  disabled={!senderId || !receiverLookup || !amount.trim() || Number(amount) <= 0}
                  className="w-full"
                >
                  Send Money
                </Button>
              </form>
            )}
          </CardContent>
        </Card>
      </main>

      <footer className="flex justify-between items-center px-8 py-4 text-sm text-muted-foreground/70 border-t border-border">
        <span>Wave Payment Platform</span>
        <span>{accounts.length} account{accounts.length !== 1 ? "s" : ""}</span>
      </footer>

      {(depositing || transferring) && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-background/80 backdrop-blur-md animate-fade-in">
          <div className="relative overflow-hidden rounded-xl border border-primary/20 bg-card px-12 py-10 text-center space-y-6 shadow-2xl max-w-sm w-full mx-4 animate-fade-slide-in">
            <div className="absolute top-0 left-0 right-0 h-[3px] bg-primary/10 overflow-hidden">
              <div className="h-full w-1/2 bg-gradient-to-r from-transparent via-primary to-transparent animate-shimmer" style={{ backgroundSize: "200% 100%" }} />
            </div>
            <div className="w-20 h-20 mx-auto rounded-full border-[3px] border-primary/20 flex items-center justify-center">
              <div className="w-10 h-10 rounded-full border-[3px] border-primary border-t-transparent animate-a-spin" />
            </div>
            <div>
              <p className="text-4xl font-mono font-bold text-foreground">
                {depositing ? formatBalance(Number(depositAmount)) : formatAmount(amount)}
              </p>
              <p className="text-sm text-muted-foreground mt-1">
                {depositing
                  ? accounts.find((a) => a.id === depositAccountId)?.name ?? "Account"
                  : `${accounts.find((a) => a.id === senderId)?.name ?? "Sender"} \u2192 ${receiverLookup?.name ?? "Receiver"}`}
              </p>
            </div>
            <p className="text-sm font-medium text-primary animate-pulse-glow-fast">
              {depositing ? "Processing deposit" : "Processing transfer"}
            </p>
          </div>
        </div>
      )}
    </>
  )
}

import { useEffect, useState, useRef, useCallback } from "react"
import { signOut } from "../lib/auth-client"
import { useUser } from "../lib/user-context"
import { Card, CardContent } from "../components/ui/card"
import { Button } from "../components/ui/button"
import { Badge } from "../components/ui/badge"
import { Skeleton } from "../components/ui/skeleton"

interface Notification {
  id: string
  title: string
  message: string
  type: "info" | "warning" | "error"
  timestamp: string
  read: boolean
}

interface StandardResponse<T> {
  ok: boolean
  status: number
  message: string
  data?: T
  error?: string
}

function statusVariant(status: string): "default" | "secondary" | "destructive" {
  if (status === "connected") return "default"
  if (status === "disconnected") return "destructive"
  return "secondary"
}

function statusLabel(status: string): string {
  if (status === "connected") return "Live"
  if (status === "disconnected") return "Disconnected"
  return "Connecting"
}

export default function NotificationPage() {
  const user = useUser()
  const [notifications, setNotifications] = useState<Notification[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [connectionStatus, setConnectionStatus] = useState<"connected" | "disconnected" | "connecting">("connecting")
  const eventSourceRef = useRef<EventSource | null>(null)
  const retryCountRef = useRef(0)

  const fetchInitial = useCallback(async () => {
    try {
      setLoading(true)
      const response = await fetch(`/api/notification/users/${user.id}/notifications?limit=50`)
      if (!response.ok) throw new Error(`HTTP ${response.status}`)
      const json: StandardResponse<Notification[]> = await response.json()
      setNotifications(json.data ?? [])
      setError(null)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to load")
      setNotifications([])
    } finally {
      setLoading(false)
    }
  }, [user.id])

  const connectSSE = useCallback(() => {
    if (eventSourceRef.current) {
      eventSourceRef.current.close()
    }

    setConnectionStatus("connecting")
    const es = new EventSource(`/api/notification/users/${user.id}/notifications/stream`)
    eventSourceRef.current = es

    es.onopen = () => {
      setConnectionStatus("connected")
      retryCountRef.current = 0
    }

    es.onmessage = (event) => {
      try {
        const parsed = JSON.parse(event.data)
        const items: Notification[] = parsed.result ?? parsed.data ?? []
        if (items.length > 0) {
          setNotifications((prev) => {
            const existing = new Set(prev.map((n) => n.id))
            const newItems = items.filter((n) => !existing.has(n.id))
            return [...newItems, ...prev].slice(0, 50)
          })
        }
      } catch {
        // ping or parse error - ignore
      }
    }

    es.onerror = () => {
      setConnectionStatus("disconnected")
      es.close()
      eventSourceRef.current = null

      const delay = Math.min(1000 * 2 ** retryCountRef.current, 30000)
      retryCountRef.current += 1
      setTimeout(connectSSE, delay)
    }
  }, [user.id])

  useEffect(() => {
    fetchInitial()
    connectSSE()
    return () => {
      if (eventSourceRef.current) eventSourceRef.current.close()
    }
  }, [fetchInitial, connectSSE])

  const dismissNotification = (id: string) => {
    setNotifications((prev) => prev.filter((n) => n.id !== id))
  }

  const markRead = (id: string) => {
    setNotifications((prev) =>
      prev.map((n) => (n.id === id ? { ...n, read: true } : n))
    )
  }

  const handleSignOut = async () => {
    await signOut()
  }

  return (
    <>
      <header className="flex items-center justify-between flex-wrap gap-3 px-8 py-5 border-b border-border">
        <h1 className="text-2xl font-bold tracking-tight text-foreground">Notifications</h1>
        <div className="flex items-center gap-2">
          <Badge variant={statusVariant(connectionStatus)}>
            <span className={`mr-1.5 h-1.5 w-1.5 rounded-full ${
              connectionStatus === "connected" ? "bg-current animate-pulse-glow" :
              connectionStatus === "disconnected" ? "bg-current" :
              "bg-current animate-pulse-glow-fast"
            }`} />
            {statusLabel(connectionStatus)}
          </Badge>
          <div className="flex flex-col items-end leading-tight px-3 border-r border-border">
            <span className="text-sm font-semibold text-foreground">{user.name}</span>
            <span className="text-xs text-muted-foreground">{user.email}</span>
          </div>
          <Button variant="outline" size="sm" onClick={fetchInitial}>
            Refresh
          </Button>
          <Button variant="destructive" size="sm" onClick={handleSignOut}>
            Sign Out
          </Button>
        </div>
      </header>

      <main className="flex-1 mx-auto w-full max-w-2xl px-8 py-6">
        {loading && (
          <div className="flex flex-col gap-2">
            {Array.from({ length: 4 }).map((_, i) => (
              <Skeleton key={i} data-testid="skeleton-card" className="h-20 w-full rounded-lg" />
            ))}
          </div>
        )}

        {error && !loading && (
          <div className="flex flex-col items-center justify-center gap-4 py-16 text-center">
            <div className="flex h-12 w-12 items-center justify-center rounded-full bg-destructive/10 border-2 border-destructive/30 text-destructive text-lg font-bold">
              !
            </div>
            <p className="text-muted-foreground">{error}</p>
            <Button variant="outline" onClick={fetchInitial}>
              Retry
            </Button>
          </div>
        )}

        {!loading && !error && notifications.length === 0 && (
          <div className="flex flex-col items-center justify-center gap-2 py-16 text-center">
            <h2 className="text-base font-semibold text-muted-foreground">No notifications</h2>
            <p className="text-sm text-muted-foreground/60">
              New notifications will appear here in real time.
            </p>
          </div>
