  try {
    const res = await fetch(`http://localhost:3000/api/${url}`);
    return await res.json() as WaveResponse<T>;
  } catch (error) {
    console.error("Error in TryCatchAction:", error);
    throw error;
  };
}

export async function fetchTransactionsAction(userId: TUserId): Promise<WaveResponse<ITransaction[]>> {
  return await TryCatchAction<ITransaction[]>(`transactions?userId=${userId}`);
};

